package com.morongaming.forsakenrealm;
import android.content.Context;import android.graphics.*;import android.view.*;import org.json.*;
/** Approved selection composition with one real saved character, equipped preview, details and item slots. */
final class PlayView extends View {
 interface Host{JSONObject state();void enter();void back();default void navigate(int n){back();}}
 final Host host;final MenuFrame f=new MenuFrame();final ScenePainter painter=new ScenePainter();final MenuArt art;boolean pressed;float downX,downY;
 PlayView(Context c,Host h){super(c);host=h;art=MenuArt.get(c);setContentDescription("Forsaken Realm character selection. Saved survivor, actual equipment and companion. Enter World at bottom right.");}
 private String title(String s){return s.isEmpty()?"Survivor":s.substring(0,1).toUpperCase()+s.substring(1);}
 protected void onDraw(Canvas c){f.begin(c,this);f.brand(c);f.navigation(c,0);JSONObject state=host.state(),you=state==null?null:state.optJSONObject("you"),account=state==null?null:state.optJSONObject("account"),pet=state==null?null:state.optJSONObject("companion");if(you==null||account==null){f.text(c,"Connecting to your saved survivor…",40,140,22,850);c.restore();return;}
 String role=title(you.optString("role")),name=account.optString("username",account.optString("id"));f.panel(c,24,78,256,359,false);f.text(c,"SELECT CHARACTER",40,108,20,224);f.panel(c,38,127,228,100,true);art.item(c,you.optString("equippedWeapon"),48,139,55);f.text(c,name,113,156,20,141);f.text(c,"Level "+you.optInt("level",1)+" · "+role,113,183,15,141);f.text(c,"YOUR ACTIVE SURVIVOR",51,213,12,205);f.text(c,"ALLEGIANCE",41,264,13,220);f.text(c,title(you.optString("faction")),41,289,20,220);f.wrap(c,"Your saved survivor, equipment and progress stay with your account.",41,331,220,3);f.text(c,"PERSISTENT CHARACTER",41,414,12,220,0xffc7ad75);
 f.text(c,"YOUR SURVIVOR",342,107,17,240);art.survivor(c,you.optString("appearance","male-1"),you.optString("equippedArmour"),new RectF(319,120,594,426));if(pet!=null){f.panel(c,304,350,114,78,false);art.companionPortrait(c,pet,new RectF(309,355,360,423));f.text(c,title(pet.optString("kind")),365,379,13,49);f.text(c,"COMPANION",310,420,10,99);}
 f.panel(c,634,78,302,96,false);f.text(c,"WORLD INFORMATION",650,106,18,270);f.text(c,"Persistent Forsaken Realm",650,131,15,270);f.text(c,"Two protected Trader Towns",650,155,14,270);f.panel(c,634,185,302,113,false);f.text(c,"CHARACTER DETAILS",650,212,18,270);f.text(c,"Role: "+role+" · Level "+you.optInt("level",1),650,237,15,270);f.text(c,"Health: "+you.optInt("hp")+" / "+you.optInt("maxHp",100),650,260,15,270);f.text(c,pet==null?"Companion: none":("Companion: "+title(pet.optString("kind"))),650,283,15,270);
 f.panel(c,634,309,302,128,false);f.text(c,"CURRENT EQUIPMENT",650,336,18,270);JSONObject gear=you.optJSONObject("armorSlots"),bag=you.optJSONObject("inventory");String[] slots={"helmet","chest","gloves","leggings","boots","shield","hands","backpack"};for(int i=0;i<slots.length;i++){String slot=slots[i],id=i==6?you.optString("equippedWeapon"):i==5?(you.optBoolean("equippedShield")?"shield":""):i==7?you.optString("equippedBackpack"):gear==null?(i==0?you.optString("equippedHelmet"):i==1?you.optString("equippedArmour"):""):gear.optString(slot);if(id.equals("null")||bag==null||bag.optInt(id)<1)id="";float x=650+i*33;f.panel(c,x,351,30,57,false);if(!id.isEmpty())art.item(c,id,x+1,359,28);f.text(c,slot.substring(0,1).toUpperCase(),x+10,400,11,20,0xffb3a17b);}
 JSONObject purse=you.optJSONObject("coinPouch");f.text(c,purse==null?"Carried coins are stored in your belt pouch":purse.optLong("copper")+" copper   "+purse.optLong("silver")+" silver   "+purse.optLong("gold")+" gold",24,477,15,585);f.text(c,"Full loot outside protected towns",24,503,14,585,0xffc0b295);f.panel(c,634,455,302,60,true);f.text(c,"ENTER WORLD",693,493,23,237);c.restore();}
 public boolean performClick(){super.performClick();return true;}
 public boolean onTouchEvent(MotionEvent e){float x=f.x(e.getX()),y=f.y(e.getY());int type=e.getActionMasked();if(type==MotionEvent.ACTION_DOWN){pressed=true;downX=x;downY=y;return true;}if(type==MotionEvent.ACTION_CANCEL||type==MotionEvent.ACTION_POINTER_DOWN){pressed=false;return true;}if(type!=MotionEvent.ACTION_UP||!pressed)return true;pressed=false;if(Math.hypot(x-downX,y-downY)>14)return true;performClick();int nav=f.navigationHit(x,y);if(nav>=0)host.navigate(nav);else if(x<170&&y<60)host.back();else if(x>=634&&x<=936&&y>=455&&y<=515)host.enter();return true;}
}

